#:property AllowUnsafeBlocks=true

Console.WriteLine($"IntPtr.Size = {IntPtr.Size} (expecting 8 on 64-bit)");

// stackalloc nint into Span<nint>
Span<nint> nints = stackalloc nint[4];
for (int i = 0; i < nints.Length; i++)
    nints[i] = i * 10;

Console.Write("Span<nint>:  ");
foreach (var v in nints)
    Console.Write($"{v} ");
Console.WriteLine();

// stackalloc nuint into Span<nuint>
Span<nuint> nuints = stackalloc nuint[4];
for (int i = 0; i < nuints.Length; i++)
    nuints[i] = (nuint)(i * 100);

Console.Write("Span<nuint>: ");
foreach (var v in nuints)
    Console.Write($"{v} ");
Console.WriteLine();

Console.WriteLine("Success — stackalloc Span<nint> and Span<nuint> both work.");

